import test from 'node:test';
import assert from 'node:assert/strict';
import {csvCell,csvChunks,jsonChunks} from '../src/modules/insight/transfer-export.js';
import {validateDocument} from '../src/modules/insight/transfer-validation.js';
import {insightScenario} from './insight-helpers.js';
async function bundle(s) {
  const label=(await s.api('POST','/projects/'+s.project.id+'/labels',{name:'Transfer label',color:'#123abc'})).data.label;
  const parent=(await s.api('POST','/projects/'+s.project.id+'/issues',{title:'Parent'})).data.issue;
  await s.api('PATCH','/issues/'+s.issue.id,{parentId:parent.id,labelIds:[label.id],dueDate:'2028-02-29',description:'Quoted "text"\nMultiline body'});
  await s.member('POST','/issues/'+s.issue.id+'/comments',{body:'Transfer **comment**'});
  await s.api('POST','/issues/'+s.issue.id+'/relations',{targetIssueId:parent.id,kind:'relates'});
  return (await s.api('GET','/projects/'+s.project.id+'/export')).data;
}
test('JSON export streams a complete parseable document through canonical work readers',()=>insightScenario(async s=>{
  const document=await bundle(s);assert.equal(document.format,'crew.project');assert.equal(document.version,1);
  assert.equal(document.issues.length,2);assert.equal(document.comments[0].body,'Transfer **comment**');assert.equal(document.labels[0].name,'Transfer label');assert.equal(document.relations[0].kind,'relates');
  assert.deepEqual(JSON.parse([...jsonChunks(document)].join('')),document);assert.equal(validateDocument(document).issues.length,2);
}));
test('validated preview creates no project event index notification or activity state',()=>insightScenario(async s=>{
  const document=await bundle(s),before=s.server.ctx.db.prepare('SELECT count(*) n FROM projects').get().n;
  const events=[];const off=s.server.ctx.bus.subscribe(event=>events.push(event));
  try{const response=await s.api('POST','/orgs/'+s.org.id+'/import',{document,key:'COPY',preview:true});assert.equal(response.status,200);assert.equal(response.data.preview.counts.issues,2);assert.equal(s.server.ctx.db.prepare('SELECT count(*) n FROM projects').get().n,before);assert.deepEqual(events,[]);}
  finally{off();}
}));
test('atomic JSON roundtrip preserves fields parent comments labels relations authors and timestamps with new IDs',()=>insightScenario(async s=>{
  const document=await bundle(s),result=await s.api('POST','/orgs/'+s.org.id+'/import',{document,key:'COPY',name:'Imported copy'});
  assert.equal(result.status,201,JSON.stringify(result.data));const imported=result.data;
  const again=(await s.api('GET','/projects/'+imported.project.id+'/export')).data;
  assert.equal(again.issues.length,document.issues.length);assert.equal(again.comments.length,document.comments.length);assert.equal(again.relations.length,document.relations.length);
  for(const source of document.issues){const id=imported.mappings.issues[source.id],item=again.issues.find(issue=>issue.id===id);assert.notEqual(id,source.id);for(const key of ['number','title','description','priority','assigneeId','estimate','dueDate','createdBy','rank','createdAt','updatedAt'])assert.equal(item[key],source[key],key);assert.equal(item.parentId,source.parentId?imported.mappings.issues[source.parentId]:null);assert.deepEqual(item.labelIds,source.labelIds.map(id=>imported.mappings.labels[id]));}
  assert.equal(again.comments[0].authorId,document.comments[0].authorId);assert.equal(again.comments[0].createdAt,document.comments[0].createdAt);
  const search=(await s.api('GET','/search?orgId='+s.org.id+'&q=project:COPY')).data;assert.equal(search.total,2);
}));
test('number gaps reverse order and child-before-parent imports preserve numbering and next counter',()=>insightScenario(async s=>{
  await s.api('DELETE','/issues/'+s.issue.id);
  const parent=(await s.api('POST','/projects/'+s.project.id+'/issues',{title:'Number two'})).data.issue;
  const child=(await s.api('POST','/projects/'+s.project.id+'/issues',{title:'Number three',parentId:parent.id})).data.issue;
  const document=(await s.api('GET','/projects/'+s.project.id+'/export')).data;document.issues.reverse();
  assert.deepEqual(document.issues.map(issue=>issue.number),[3,2]);
  const result=await s.api('POST','/orgs/'+s.org.id+'/import',{document,key:'GAP'});assert.equal(result.status,201,JSON.stringify(result.data));
  const newIssue=(await s.api('POST','/projects/'+result.data.project.id+'/issues',{title:'Next after gap'})).data.issue;assert.equal(newIssue.number,4);
  const importedChild=(await s.api('GET','/issues/'+result.data.mappings.issues[child.id])).data.issue;assert.equal(importedChild.parentId,result.data.mappings.issues[parent.id]);
}));
test('missing references invalid timestamps and duplicate numbers yield useful errors before writes',()=>insightScenario(async s=>{
  const original=await bundle(s);
  const attempts=[document=>document.issues[0].labelIds.push('foreign'),document=>document.issues[0].statusId='foreign',document=>document.issues[0].updatedAt='bad',document=>document.issues[1].number=document.issues[0].number];
  for(const change of attempts){const document=structuredClone(original);change(document);const result=await s.api('POST','/orgs/'+s.org.id+'/import',{document,key:'BAD'});assert.equal(result.status,422);assert(result.data.error.details);}
  assert.equal(s.server.ctx.db.prepare("SELECT count(*) n FROM projects WHERE key='BAD'").get().n,0);
}));
test('parent and directed relation cycles are rejected with no partially imported project',()=>insightScenario(async s=>{
  const original=await bundle(s),parent=structuredClone(original);parent.issues[1].parentId=parent.issues[0].id;
  assert.equal((await s.api('POST','/orgs/'+s.org.id+'/import',{document:parent,key:'CYCLE'})).status,422);
  const graph=structuredClone(original);graph.relations[0].kind='blocks';graph.relations.push({...graph.relations[0],id:'reverse',sourceIssueId:graph.relations[0].targetIssueId,targetIssueId:graph.relations[0].sourceIssueId});
  assert.equal((await s.api('POST','/orgs/'+s.org.id+'/import',{document:graph,key:'CYCLE'})).status,422);
}));
test('write failure rolls back new project and suppresses all buffered public events and derived stores',()=>insightScenario(async s=>{
  const document=await bundle(s),tables=['projects','issues','comments','labels','issue_relations','activity','notifications','search_documents'];
  const census=()=>Object.fromEntries(tables.map(table=>[table,s.server.ctx.db.prepare('SELECT count(*) n FROM '+table).get().n]));
  const before=census(),events=[];const off=s.server.ctx.bus.subscribe(event=>events.push(event));
  s.server.ctx.db.exec("CREATE TEMP TRIGGER import_failure BEFORE INSERT ON comments BEGIN SELECT RAISE(ABORT,'controlled write failure'); END");
  try{const result=await s.api('POST','/orgs/'+s.org.id+'/import',{document,key:'FAIL'});assert.equal(result.status,500);assert.deepEqual(census(),before);assert.deepEqual(events,[]);}
  finally{off();s.server.ctx.db.exec('DROP TRIGGER import_failure');}
}));
test('external relation endpoints require explicit writable same-organization mappings',()=>insightScenario(async s=>{
  const other=(await s.api('POST','/orgs/'+s.org.id+'/projects',{key:'EXT',name:'External'})).data.project;
  const external=(await s.api('POST','/projects/'+other.id+'/issues',{title:'External target'})).data.issue;
  await s.api('POST','/issues/'+s.issue.id+'/relations',{targetIssueId:external.id,kind:'blocks'});
  const document=(await s.api('GET','/projects/'+s.project.id+'/export')).data;assert.equal(document.externalIssues[0].id,external.id);
  assert.equal((await s.api('POST','/orgs/'+s.org.id+'/import',{document,key:'LINK'})).status,422);
  const result=await s.api('POST','/orgs/'+s.org.id+'/import',{document,key:'LINK',externalIssueMap:{[external.id]:external.id}});assert.equal(result.status,201,JSON.stringify(result.data));
  const relations=(await s.api('GET','/issues/'+result.data.mappings.issues[s.issue.id]+'/relations')).data.items;assert.equal(relations[0].relatedIssue.id,external.id);
}));
test('import mappings reject foreign user IDs and explicit member remapping updates authors and assignees',()=>insightScenario(async s=>{
  const document=await bundle(s);
  assert.equal((await s.api('POST','/orgs/'+s.org.id+'/import',{document,key:'MAP',userMap:{[s.memberUser.id]:'foreign'}})).status,422);
  const result=await s.api('POST','/orgs/'+s.org.id+'/import',{document,key:'MAP',userMap:{[s.memberUser.id]:s.user.id}});assert.equal(result.status,201,JSON.stringify(result.data));
  const issue=(await s.api('GET','/issues/'+result.data.mappings.issues[s.issue.id])).data.issue;assert.equal(issue.assigneeId,s.user.id);
  const comments=(await s.api('GET','/issues/'+issue.id+'/comments')).data.items;assert.equal(comments[0].authorId,s.user.id);
}));
test('transfer permissions enforce scopes and organization project creation authority',()=>insightScenario(async s=>{
  const document=(await s.api('GET','/projects/'+s.project.id+'/export')).data;
  assert.equal((await s.member('POST','/orgs/'+s.org.id+'/import',{document,key:'NO'})).status,403);
  const token=(await s.api('POST','/tokens',{name:'Read only',scopes:['project:read']})).data.token;
  assert.equal((await s.api('GET','/projects/'+s.project.id+'/export',undefined,{Authorization:'Bearer '+token})).status,403);
}));
test('CSV escaping preserves quoted multiline cells and blocks whitespace-prefixed spreadsheet formulas',()=>{
  assert.equal(csvCell('a,"b"\nnext'),'"a,""b""\nnext"');
  for(const value of ['=SUM(A1)','+cmd','-cmd','@eval','  =hidden','\t+hidden'])assert.equal(csvCell(value),String.fromCharCode(34,39)+value+String.fromCharCode(34));
});
